pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));

        uint256 amount = 1 ether;
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        vm.prank(address(this));
        // Reference contract's withdrawAll sends to _recipient
        c.withdrawAll(recipient);

        uint256 recipientBalanceAfter = recipient.balance;
        uint256 contractBalanceAfter = address(c).balance;

        // For the reference, the recipient's balance must increase by exactly the amount withdrawn
        // (the contract's entire balance prior to the call).
        // Contract balance must be zero.
        assertTrue(
            contractBalanceAfter == 0 &&
            recipientBalanceAfter == recipientBalanceBefore + balanceBefore
        );
    }
}

